# Problem: find min in a rotated sorted array (no duplicates).
# Modified binary search using the rotation invariant: if arr[mid] > arr[hi], min is in (mid, hi].
def find_min_rotated(arr):
    lo, hi = 0, len(arr) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] > arr[hi]:
            lo = mid + 1  # min is to the right of mid
        else:
            hi = mid  # min is at mid or to its left
    return arr[lo]
