# BFS with map old->new to avoid revisits and handle cycles.
from collections import deque
def clone_graph(node):
    if not node:
        return None
    mapping = {node: type(node)(node.val)}
    q = deque([node])
    while q:
        cur = q.popleft()
        for nb in cur.neighbors:
            if nb not in mapping:
                mapping[nb] = type(nb)(nb.val)
                q.append(nb)
            mapping[cur].neighbors.append(mapping[nb])
